window.RP_SESSION={"id":"S-39cc952fac30","messages":[{"id":"RP-III-0130425","time":"2026-07-28T00:16:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"요즘 들어 스텔라는 제법 한가하다고 느끼고 있었다. 대부분의 일이라고 느껴지던 길드원 관리는 토르번이 담당하고, 모험가 연합과 같은 대외적인 길드에 대한 업무는 션이 담당하고 있었으니까.","characters":["P-e6655a038328"]},{"id":"RP-III-0130426","time":"2026-07-28T00:17:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"스텔라가 하는 것은 귀족들과 왕가와 같은 높은 사람들에 대한 일처리가 대부분. 물론 아예 없다고 하지는 않겠지만 일주일에 2~3일 정도는 여유를 가지면서 지내도 좋은 삶.","characters":["P-e6655a038328"]},{"id":"RP-III-0130427","time":"2026-07-28T00:17:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"어설픈 용맹의 부길드장으로 12년동안 지내면서 이렇게 편하게 지냈던 날이 있었나 싶을 정도.","characters":["P-e6655a038328"]},{"id":"RP-III-0130428","time":"2026-07-28T00:18:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"언제는 돈이 모자라고, 언제는 사건이 터지고, 언제는 길드 내부에 숨어든 왕가나 귀족의 첩자가 있고.","characters":["P-e6655a038328"]},{"id":"RP-III-0130429","time":"2026-07-28T00:18:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"힘든 옛날 이야기를 해봐야 뭐 하겠는가. 그냥 지금의 여유를 즐기면 되는 것이다.","characters":["P-e6655a038328"]},{"id":"RP-III-0130430","time":"2026-07-28T00:18:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"그렇게 카프리제가 해준 샌드위치와 언젠가 느긋하게 즐기려고 숨겨둔 홍차를 마시면서.","characters":["P-e6655a038328"]},{"id":"RP-III-0130431","time":"2026-07-28T00:19:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"길드 식당에서 스텔라는 그간 소홀히 했던 마법 서적을 틈틈히 읽기로 했다.","characters":["P-e6655a038328"]},{"id":"RP-III-0130432","time":"2026-07-28T00:19:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"저번에 읽은 종족별 마법의 발전사를 읽고서 느낀 묘한 감정이 거의 타버렸다고 생각했던 스텔라의 마법적 지식에 대한 욕구에 불을 지핀 것이다.","characters":["P-e6655a038328"]},{"id":"RP-III-0130433","time":"2026-07-28T00:43:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"스텔라는 일단 샌드위치랑 차나 마시자고 생각했다.","characters":["P-e6655a038328"]},{"id":"RP-III-0130434","time":"2026-07-28T00:43:00+09:00","room":"RP III","name":"스텔라 스타라이트","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-e6655a038328"]},{"id":"RP-III-0130435","time":"2026-07-28T00:43:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
